const businesses = $('Supabase: List Businesses').all().map((i) => i.json).filter((b) => b && b.id);
const existing = $input.all().map((i) => i.json).filter((a) => a && a.business_id && a.evidence);

// Vencimientos Modelo 303 por trimestre (año del periodo)
function deadlinesFor(year) {
  return [
    { label: '1T', deadline: new Date(`${year}-04-20`) },
    { label: '2T', deadline: new Date(`${year}-07-20`) },
    { label: '3T', deadline: new Date(`${year}-10-20`) },
    { label: '4T', deadline: new Date(`${year + 1}-01-30`) }
  ];
}

const now = new Date();
const y = now.getFullYear();

// Se incluye el año anterior: el 4T del año pasado vence el 30 de enero de este año
const next = [...deadlinesFor(y - 1), ...deadlinesFor(y), ...deadlinesFor(y + 1)]
  .filter((d) => d.deadline.getTime() >= now.getTime() - 86400000)
  .sort((a, z) => a.deadline - z.deadline)[0];

if (!next) return [];

const deadlineStr = next.deadline.toISOString().split('T')[0];
const days = Math.ceil((next.deadline - now) / 86400000);
if (days > 30) return [];

// Evita duplicar el aviso cada semana: una alerta abierta por negocio + trimestre + fecha
const already = new Set(existing.map((a) => `${a.business_id}|${a.evidence.quarter}|${a.evidence.deadline}`));

const alerts = [];
for (const b of businesses) {
  if (already.has(`${b.id}|${next.label}|${deadlineStr}`)) continue;
  alerts.push({
    json: {
      business_id: b.id,
      severity: days <= 7 ? 'high' : 'medium',
      type: 'PERIOD_DEADLINE',
      title: `Vence el Modelo 303 (${next.label}) en ${days} días`,
      description: `El plazo de presentación del Modelo 303 del trimestre ${next.label} termina el ${deadlineStr}. Revisa y concilia tus facturas pendientes.`,
      evidence: { quarter: next.label, deadline: deadlineStr, daysRemaining: days },
      entity_type: 'period',
      entity_id: null,
      source: 'n8n',
      status: 'OPEN'
    }
  });
}

return alerts;
